#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/wait.h>
#include <unistd.h>

// Every message is framed: an int length, then that many bytes.
void send_msg(int fd, const char *text) {
    int len = (int)strlen(text);
    send(fd, &len, sizeof len, 0);
    send(fd, text, len, 0);
}

int recv_msg(int fd, char *buf, int room) {
    int len;
    if (recv(fd, &len, sizeof len, MSG_WAITALL) != sizeof len) return -1;
    if (len < 0 || len >= room) return -1;
    if (len > 0 && recv(fd, buf, len, MSG_WAITALL) != len) return -1;
    buf[len] = '\0';
    return len;
}

void serve(int fd) {
    char words[50][32];
    int count = 0;
    while (count < 50 && recv_msg(fd, words[count], sizeof words[count]) >= 0) count++;

    char reply[2048] = "";
    for (int i = count - 1; i >= 0; i--) {
        if (i < count - 1) strcat(reply, " ");
        strcat(reply, words[i]);
    }
    send_msg(fd, reply);
}

int main(void) {
    int fds[2];
    if (socketpair(AF_UNIX, SOCK_STREAM, 0, fds) == -1) {
        perror("socketpair");
        return 1;
    }
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 1;
    }
    if (pid == 0) {
        close(fds[0]);
        serve(fds[1]);
        close(fds[1]);
        _exit(0);
    }
    close(fds[1]);

    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        char word[32];
        scanf("%31s", word);
        send_msg(fds[0], word);
    }
    shutdown(fds[0], SHUT_WR);

    char reply[2048];
    if (recv_msg(fds[0], reply, sizeof reply) < 0) strcpy(reply, "(no reply)");
    waitpid(pid, NULL, 0);
    printf("relay: [%s]\n", reply);
    close(fds[0]);
    return 0;
}
